pages=[]
def page(title,body,theme='',label='Recommended system'):
    i=len(pages)+1
    pages.append(f'<section class="page {theme}" id="p{i}"><div class="eyebrow">{label} / {i:02d}</div>{title}{body}<div class="footer"><span>HANDA UNCLE · VISUAL STYLE GUIDE · 08 OCT 2026</span><span>{i:02d} / 11</span></div></section>')

page('',f'''<div class="cover-copy"><img class="logo" src="{logo}" alt="Official Handa Uncle logo"><div style="height:68px"></div><p class="eyebrow">Brand direction · Version 1.0</p><h1>Make sense<br>of your money.</h1><p class="lede">A visual system for Handa Uncle, Ravi Handa and the allied Desi FIRE Podcast.</p><div class="rule"></div><p style="font-size:17px;max-width:490px">Calm product design. Human explanations. Clear numbers.<br>Built from the live website, app listing and social pages.</p><p class="small" style="margin-top:32px">Existing assets and measured website styles are labelled observed.<br>New rules and templates are labelled proposed.</p></div><img class="cover-art" src="{hero}" alt="Official website phone mockup">''','ice','Research-led visual style guide')

page('<h2>What the brand already says.</h2>',f'''<p class="lede">The product promises a clearer financial picture. Ravi supplies the human trust. Desi FIRE supplies the conversations and the retirement context.</p><div class="grid three"><div class="card"><span class="tag">Observed · website + app</span><h3>Handa Uncle</h3><p>Personal CFO positioning, an angular white emblem, blue gradients, pale blue backgrounds and real interface imagery.</p><img src="{store}" style="height:250px;margin:18px auto 0;object-fit:contain" alt="Official app store promotional image"></div><div class="card"><span class="tag">Observed · Instagram</span><h3>Ravi and the community</h3><p>Founder appearances, educational reels, FIRE events and the recurring Finance from zero series. The sampled reel pairs a presenter with a simple labelled chart.</p><div class="rule"></div><h3 style="color:var(--blue)">Making sense<br>of your money.</h3><p class="small">Current @handauncle bio language.</p></div><div class="card"><span class="tag">Observed · YouTube</span><h3>Desi FIRE Podcast</h3><p>Red avatar, yellow FIRE badge and white display lettering. Recent thumbnails also use the blue Handa Uncle emblem, large topic text and Ravi or guest faces.</p><img src="{thumb2}" style="margin-top:20px;border-radius:12px" alt="Observed senior living video thumbnail"></div></div><p class="source">Sources: <a href="https://www.handauncle.com/">Website</a> · <a href="https://play.google.com/store/apps/details?id=com.handauncle.handauncle&hl=en_IN">Google Play</a> · <a href="https://www.instagram.com/handauncle/">Instagram</a> · <a href="https://www.youtube.com/@desifirepodcast">YouTube</a></p>''',label='Observed evidence')

page('<h2>One family. Clear roles.</h2>',f'''<p class="lede">Keep the existing Handa Uncle identity. Give the podcast an endorsed relationship without replacing its recognisable red-and-yellow artwork.</p><div class="grid three"><div class="card"><span class="tag proposed">Proposed · hierarchy</span><img src="{logo}" class="logo" alt="Handa Uncle logo"><div class="rule"></div><h3>Product and education</h3><p>Lead with Handa Uncle on the website, app, explainers, calculators and product campaigns.</p></div><div class="card"><span class="tag proposed">Proposed · founder credit</span><h3 style="font-size:32px;color:var(--deep)">Ravi Handa</h3><p>Founder, Handa Uncle<br>Host, Desi FIRE Podcast</p><div class="rule"></div><p>Use his name and a real photograph for interviews, events and first-person stories. Keep brand marks secondary to the speaker.</p></div><div class="card"><span class="tag proposed">Proposed · endorsement</span><h3 style="font-size:27px">Desi FIRE Podcast</h3><p>With Ravi Handa</p><div class="rule"></div><img src="{logo}" style="width:175px" alt="Handa Uncle endorsement"><p style="margin-top:15px">Keep the original podcast artwork for channel avatars and covers. Use this editorial relationship on new episode layouts.</p></div></div><div class="grid two" style="margin-top:24px"><div class="sample"><span class="tag">Observed · supplied website asset</span><img src="{logo}" style="width:260px;margin:12px 0" alt="Primary official logo"><p class="small">Proposed minimum width 140 px for the full lockup. Clear space on every side equals half the emblem height. Use the native asset proportions.</p></div><div class="sample" style="background:var(--deep)"><span class="tag">Observed · reverse asset</span><img src="{white}" style="width:260px;margin:12px 0" alt="Official reverse logo"><p class="small" style="color:#c4d8ef">Use the official white asset on blue. Do not redraw the emblem, stretch the lockup, add glow or turn the podcast logo blue.</p></div></div><p class="source">Logo files were exported from the live website. Spacing, minimum sizes and endorsement rules are recommendations.</p>''')

palette=[('CFO blue','#0054AC','Observed · body / cards'),('Deep blue','#002E5F','Observed · gradient start'),('Bright blue','#005FC5','Observed · gradient end'),('Ice','#EEF5FD','Observed · page background'),('Warm paper','#F7F5F0','Observed · lower sections'),('Ink','#0F172A','Observed · base text')]
swatches='<div class="swatches">'+''.join(f'<div class="swatch"><div class="colour" style="background:{hex};color:{"white" if n<3 or n==5 else "#002E5F"}">{name}</div><div class="meta"><code>{hex}</code><span>{desc}</span></div></div>' for n,(name,hex,desc) in enumerate(palette))+'</div>'
page('<h2>Blue carries the product.</h2>',f'''<p class="lede">Use the website’s measured colours as the foundation. Keep finance screens quiet and reserve stronger contrast for actions and campaign headlines.</p>{swatches}<div class="grid two"><div class="card"><span class="tag proposed">Proposed · usage ratio</span><h3>70% light · 20% blue · 10% detail</h3><p>Light surfaces provide reading room. Blue anchors headings, buttons and brand marks. Neutral text and data colours provide the final layer.</p><div style="display:flex;height:28px;margin-top:18px;border-radius:8px;overflow:hidden"><div style="width:70%;background:var(--ice)"></div><div style="width:20%;background:var(--blue)"></div><div style="width:10%;background:var(--ink)"></div></div></div><div class="card"><span class="tag proposed">Proposed · supporting colours</span><p><b>Success #177454</b> for positive states. <b>Risk #B42318</b> for errors or losses. <b>Muted #475569</b> for secondary text. Podcast yellow <b>#FFE13A</b> and red <b>#EC172B</b> are recommended approximations of observed artwork, not sampled master values.</p></div></div><div class="note">Accessibility check: white on #0054AC is 7.3:1; #0054AC on #EEF5FD is 6.7:1. #0F172A on #F7F5F0 is 16.4:1. Yellow needs dark text. Label changes and errors in words as well as colour.</div><p class="source">Measured via computed styles on handauncle.com. Ratios rounded; proposed text pairs exceed 4.5:1.</p>''',label='Observed palette + proposed use')

page('<h2>Inter. Plain, legible, confident.</h2>','''<p class="lede">The live site declares Inter. Keep it as the shared family and use weight, spacing and scale to organise information.</p><div class="split"><div><div class="sample"><p style="font-size:55px;line-height:1.02;letter-spacing:-2px;font-weight:500;color:var(--deep)">Your Personal CFO<br>for Every Financial<br>Decision.</p><p class="caption">Observed headline language. Proposed specimen layout.</p></div><div style="margin-top:24px"><p style="font-size:28px;font-weight:600;color:var(--blue)">Everything you own. One place.</p><p style="margin-top:12px;max-width:500px">See your assets, loans and family holdings together. Start with one account and build the full picture.</p><p class="caption">Proposed supporting copy · 16 px / 24 px</p></div></div><div><table class="table"><tr><th>Role</th><th>Desktop / mobile</th><th>Weight</th></tr><tr><td>Hero</td><td>60 / 36 px</td><td>500</td></tr><tr><td>Section</td><td>40 / 28 px</td><td>600</td></tr><tr><td>Card title</td><td>24 / 20 px</td><td>600</td></tr><tr><td>Body</td><td>16 / 16 px</td><td>400</td></tr><tr><td>Label</td><td>12 / 12 px</td><td>600</td></tr><tr><td>Financial value</td><td>32 / 28 px</td><td>600</td></tr></table><p class="small" style="margin-top:18px">Proposed responsive scale. Observed website examples include a 60 px / 500 hero, 30 px / 600 feature titles, 24 px / 500 card titles and 16 px body copy at the inspected viewport.</p><div class="rule"></div><h3>Numbers should be easy to compare.</h3><p class="value">₹12,50,000</p><p class="small">Use Indian grouping and tabular numerals. Write lakh and crore for editorial context. Always identify a period, unit and whether a number is estimated.</p><p class="small" style="margin-top:16px">Body line-height 1.5. Limit text columns to 60–70 characters. Use sentence case; reserve all caps for short thumbnail hooks and section labels.</p></div></div>''',label='Observed family + proposed type scale')

page('<h2>The human face of the numbers.</h2>',f'''<p class="lede">Use real people to explain money. Use interface imagery to explain the product. Let the existing illustrated uncle welcome users into the system.</p><div class="grid three"><div class="card"><img src="{thumb3}" style="border-radius:10px" alt="Observed JL Collins and Ravi thumbnail"><span class="tag" style="margin-top:15px">Observed · editorial</span><h3>Ravi and guests</h3><p>Use approved photographs or actual episode stills. Keep expressions natural, glasses and skin tone accurate, and backgrounds simple.</p></div><div class="card"><img src="{store}" style="height:200px;margin:auto;object-fit:contain" alt="Existing illustrated Handa Uncle character"><span class="tag" style="margin-top:15px">Observed · mascot</span><h3>The illustrated uncle</h3><p>Reuse approved artwork for onboarding and app marketing. Keep the blue clothing, glasses and warm expression. Do not generate a substitute founder likeness.</p></div><div class="card"><img src="{planning}" style="height:200px;object-fit:contain;margin:auto" alt="Official financial planning interface asset"><span class="tag">Observed · interface</span><h3>The product itself</h3><p>Use current screenshots with synthetic or approved demo data. Show one feature at a time and preserve readable labels.</p></div></div><div class="grid two" style="margin-top:24px"><div><h3>Proposed graphic language</h3><p class="small">Fine blue grids, restrained line icons, rounded cards and labelled diagrams. Use gradients on hero backgrounds and campaign panels; use solid text on busy backgrounds.</p></div><div><h3>Proposed chart rules</h3><p class="small">Direct labels, visible units, dates and source notes. Blue for the primary series; a second colour plus dashed or solid lines for comparison. Avoid 3D pies, unlabeled arrows and decorative rising graphs.</p></div></div>''')

page('<h2>A calm product surface.</h2>',f'''<p class="lede">Translate the current blue-and-light direction into consistent controls. These are proposed UI examples with fictional data, not screens captured from the app.</p><div class="grid" style="grid-template-columns:1.05fr 1.05fr .9fr"><div class="sample"><img class="logo" src="{logo}" style="width:190px;margin-bottom:30px" alt="Handa Uncle"><p class="metric">Family net worth · illustrative</p><p class="value" style="color:var(--deep)">₹42,50,000</p><p class="small">As of 8 Oct 2026 · demo data</p><div class="chart"><svg viewBox="0 0 300 120" aria-label="Illustrative net worth trend"><path d="M0 108 L55 82 L100 90 L155 61 L205 70 L252 33 L300 17" fill="none" stroke="#0054AC" stroke-width="3"/><circle cx="300" cy="17" r="5" fill="#0054AC"/></svg></div><div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted)"><span>May</span><span>Oct</span></div><div class="rule"></div><span class="button">View holdings</span><p class="caption">Chart is schematic. A production chart needs exact labels and accessible values.</p></div><div><div class="sample"><h3>Action hierarchy</h3><span class="button">Connect an account</span><div style="height:12px"></div><span class="button secondary">Add manually</span><p class="caption">One primary action per task. Prefer specific verbs over “Continue” when the next step is known.</p></div><div class="sample" style="margin-top:18px"><h3>Reusable dimensions</h3><p class="small">Spacing 4, 8, 12, 16, 24, 32, 48 px.<br>Card radius 16 px. Input radius 10 px.<br>Buttons and touch targets ≥44 px.<br>Desktop grid 12 columns; mobile 4.<br>Focus ring 2 px blue, offset 2 px.</p></div><div class="sample" style="margin-top:18px"><h3 style="color:#B42318;font-size:17px">We couldn’t refresh this account.</h3><p class="small">Last updated 7 Oct. Try again or reconnect.</p></div></div><div class="phone"><img src="{logo}" style="width:170px" alt="Handa Uncle"><div class="message">Can I plan for retirement?</div><p style="font-size:14px">Let’s start with your monthly spending, savings and target age.</p><div class="rule"></div><p class="small">Projection<br>Based on your assumptions</p><p class="value" style="font-size:26px;margin-top:10px">Review your plan</p><span class="button" style="margin-top:20px">Open FIRE planner</span><p class="caption">Concept only. Feature names are grounded in the public site.</p></div></div>''',label='Proposed interface system')

page('<h2>Teach one thing per frame.</h2>',f'''<p class="lede">Give existing Instagram series a repeatable layout. The examples below are proposed templates; they are not published brand posts.</p><div class="grid three"><div><div class="social"><img src="{logo}" class="logo" alt="Handa Uncle"><p class="eyebrow" style="margin-top:25px">Finance from zero · 07</p><h3>Revenue<br>isn’t profit.</h3><p style="font-size:18px">Revenue − costs<br>= profit</p><div class="chart" style="height:80px;margin-top:28px"><svg viewBox="0 0 250 80"><path d="M0 70 L250 10" stroke="#0054AC" stroke-width="3"/><path d="M0 76 L250 38" stroke="#177454" stroke-width="3"/></svg></div><div class="bottom">Learn the difference →</div></div><p class="caption">Carousel cover · 1080 × 1350</p></div><div><div class="social dark"><img src="{white}" class="logo" alt="Handa Uncle"><p class="eyebrow" style="margin-top:25px;color:#a5c8f3">Ask Handa Uncle</p><h3>What does<br>your family<br>own?</h3><p style="font-size:17px;color:#c4d8ef">Accounts. Investments.<br>Loans. One picture.</p><div class="bottom" style="border-color:#ffffff45">Explore Handa Uncle →</div></div><p class="caption">Product explainer · 1080 × 1350</p></div><div><div class="social"><p class="eyebrow">Desi FIRE Podcast</p><h3 style="margin-top:32px">What does<br>enough<br>look like?</h3><div style="height:112px;border-radius:10px;background:#d8e7f8;display:flex;align-items:center;justify-content:center;color:var(--blue);font-size:13px">Approved episode still</div><p style="font-size:14px;margin-top:15px">With Ravi Handa</p><div class="bottom">Watch the conversation →</div></div><p class="caption">Podcast clip cover · 1080 × 1350</p></div></div><div class="specs"><div><strong>Carousel</strong>64 px outer margin; headline 64–88 px; body 32–40 px. Slides: question, explanation, example, next step.</div><div><strong>Reels / stories</strong>1080 × 1920. Keep key content 90 px from sides, 250 px from top and 340 px from bottom. Check the current app overlay before export.</div><div><strong>Presenter clips</strong>Keep the presenter visible. Use two-line captions, readable contrast and one visual example. Avoid animated logos or neon effects competing with the lesson.</div></div>''',label='Proposed social templates')

page('<h2>Desi FIRE keeps its voice.</h2>',f'''<p class="lede">Keep the established podcast cover. Standardise new episode thumbnails around one question, real faces and a consistent Handa Uncle endorsement.</p><div class="refs"><div><img src="{thumb1}" alt="Observed investment episode thumbnail"><p>Observed · investment conversation</p></div><div><img src="{thumb2}" alt="Observed senior living thumbnail"><p>Observed · large topic hook + Ravi</p></div><div><img src="{thumb3}" alt="Observed JL Collins episode thumbnail"><p>Observed · guest + Ravi split</p></div></div><div class="grid two" style="margin-top:24px"><div><div class="thumbnail"><div class="portrait">Place approved Ravi<br>or guest portrait here</div><div style="position:relative;width:56%"><p class="brand">DESI FIRE PODCAST</p><h3>HOW MUCH<br>IS <span class="yellow">ENOUGH?</span></h3><p style="font-size:13px">With Ravi Handa</p></div></div><p class="caption">Proposed 1280 × 720 template. Placeholder portrait area is intentional; this is a layout specification.</p></div><div><h3>Thumbnail rules</h3><ul><li>One hook, 3–6 words. One face or a clear two-person split.</li><li>Headline 72–100 px at 1280 × 720. Keep a 48 px outer margin and the bottom-right duration area clear.</li><li>Blue Handa Uncle mark in a fixed corner. Use yellow only to highlight one phrase.</li><li>Retain the existing red/yellow podcast cover on channel and audio platforms. Do not reconstruct the original logo from text.</li></ul><p class="small">Proposed display face: Inter ExtraBold. The original podcast logo’s exact font was not verified.</p></div></div><p class="source">Observed references: <a href="https://www.youtube.com/watch?v=YFEW0Rk0VEg">Investment conversation</a> · <a href="https://www.youtube.com/watch?v=04CcSLvEUV4">Senior living</a> · <a href="https://www.youtube.com/watch?v=XTciduL5s9U">JL Collins</a></p>''')

page('<h2>Speak like a useful uncle.</h2>','''<p class="lede">The voice should help someone understand a decision. Use direct language, specific examples and a clear next step.</p><div class="grid two"><div class="card"><span class="tag proposed">Proposed · write this</span><h3>“See your family’s finances in one place.”</h3><p>Name the outcome. Explain unfamiliar terms. Say which information or assumptions an answer depends on.</p><div class="rule"></div><h3>“What happens if your expenses change?”</h3><p>Invite exploration. Use questions for podcast hooks and explanations for the product.</p><div class="rule"></div><h3>“Finance from zero: emergency fund kya hota hai?”</h3><p>Hinglish is appropriate for a series that already uses it. Choose a language for the full piece and keep captions consistent.</p></div><div class="card"><span class="tag proposed">Proposed · avoid this</span><h3>“Unlock financial nirvana with AI.”</h3><p>Replace broad promises with the action or feature the user can see.</p><div class="rule"></div><h3>“Retire at 40, guaranteed.”</h3><p>Do not turn Ravi’s personal story into a universal outcome. Present projections as estimates with assumptions.</p><div class="rule"></div><h3>“India’s most trusted.”</h3><p>The site uses this phrase. Treat it as existing promotional copy, not a verified fact or a standard to repeat without evidence.</p></div></div><div class="note">Claim handling for design: the app artwork says “SEBI Registered Investment Advisory” and “0% Zero Commission.” This research did not independently verify registration or the scope of those claims. Use approved wording and entity details before placing them in new campaigns.</div><p class="source">Tone informed by <a href="https://www.instagram.com/ravihanda/">Ravi’s profile</a>, <a href="https://www.instagram.com/handauncle/reel/Dd1Zf2JTO4e/">Finance from zero</a> and the <a href="https://www.youtube.com/@desifirepodcast">podcast description</a>. Examples are proposed copy, not Ravi quotations.</p>''')

page('<h2>Source record and handoff.</h2>','''<p class="section-note">Browser research completed 8 October 2026. This guide documents public-facing evidence and proposes a consistent design system.</p><table class="table sources"><tr><th>Surface</th><th>Verified observation</th><th>Source / scope</th></tr><tr><td>Website</td><td>Blue logo assets; Inter declaration; measured palette; CFO, family wealth and FIRE planner messaging.</td><td><a href="https://www.handauncle.com/">handauncle.com</a><br>Rendered homepage and computed styles.</td></tr><tr><td>Android app</td><td>Hijli Labs listing; public screenshot artwork; illustrated uncle; Indian personal finance positioning.</td><td><a href="https://play.google.com/store/apps/details?id=com.handauncle.handauncle&hl=en_IN">Google Play listing</a><br>Store material only. Authenticated app flows not tested.</td></tr><tr><td>Instagram</td><td>@handauncle education and event content; @ravihanda bio identifies him as a FIRE enthusiast and podcast host.</td><td><a href="https://www.instagram.com/handauncle/">@handauncle</a> · <a href="https://www.instagram.com/ravihanda/">@ravihanda</a><br>Profile grids and one sampled reel.</td></tr><tr><td>YouTube</td><td>Desi FIRE channel, founder-led interviews and FIRE content; red/yellow identity; blue marks on recent thumbnails.</td><td><a href="https://www.youtube.com/@desifirepodcast">@desifirepodcast</a><br>Channel description and recent video grid.</td></tr><tr><td>Facebook</td><td>HandaUncle candidate links to the site but shows a default avatar and no posts. Ownership not verified. No clear Desi FIRE page found.</td><td><a href="https://www.facebook.com/profile.php?id=61593790340815">Candidate page</a> · <a href="https://www.facebook.com/search/pages/?q=desi%20fire%20podcast">Podcast page search</a><br>Excluded from visual design evidence.</td></tr></table><h3 style="margin-top:25px">Apply in this order</h3><div class="checklist"><div>1. Confirm the official Facebook URL and master podcast artwork.</div><div>2. Share this guide’s palette, type scale and logo assets with the team.</div><div>3. Build the three social templates and one episode thumbnail template.</div><div>4. Bring UI spacing, data labels and focus states into the same system.</div></div><p class="small" style="margin-top:18px">All source imagery belongs to its respective owners and is included as reference material. Proposed layouts are reviewable concepts, not approved brand standards. Exact app fonts, podcast master colours and any separate podcast Instagram account remain unverified.</p>''',label='Research scope + implementation')

html='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Handa Uncle · Visual style guide</title><style>'+css+'</style></head><body><nav class="toolbar"><span>Handa Uncle / Visual style guide</span><div><a href="#p4">Palette</a><a href="#p8">Social</a><a href="#p11">Sources</a><button onclick="window.print()">Print / save PDF</button></div></nav>'+''.join(pages)+'</body></html>'
(OUT/'handa-uncle-visual-style-guide.html').write_text(html,encoding='utf-8')
tokens={'status':'Proposed design tokens grounded in observed website colours','research_date':'2026-10-08','color':{'brand':'#0054AC','deep':'#002E5F','bright':'#005FC5','surface':'#EEF5FD','paper':'#F7F5F0','ink':'#0F172A','muted':'#475569','success':'#177454','risk':'#B42318','podcast_yellow_proposed':'#FFE13A','podcast_red_proposed':'#EC172B'},'font':{'family':'Inter, Segoe UI, Arial, sans-serif','hero':{'desktop':60,'mobile':36,'weight':500},'body':{'size':16,'lineHeight':1.5},'numeric':'tabular-nums'},'spacing':[4,8,12,16,24,32,48],'radius':{'card':16,'control':10},'touchTargetMin':44}
(OUT/'design-tokens.json').write_text(json.dumps(tokens,indent=2),encoding='utf-8')
